package telemetry

// Пороги заряда батареи в процентах.
const (
	WarningLevel = 40
	AlarmLevel   = 20
)

// Severity — уровень важности тревоги.
type Severity int

const (
	SeverityNone Severity = iota
	SeverityWarning
	SeverityAlarm
)

internal/telemetry/battery.go: BatterySeverity
// BatterySeverity возвращает уровень тревоги для заряда батареи: предупреждение ниже сорока
// процентов, тревога ниже двадцати.
func BatterySeverity(percent int) Severity {
	switch {
	case percent < AlarmLevel:
		return SeverityAlarm
	case percent < WarningLevel:
		return SeverityWarning
	default:
		return SeverityNone
	}
}

internal/telemetry/fog.go: ShouldSoundHorn
// ShouldSoundHorn решает, нужен ли туманный сигнал при данной видимости. Горн, который уже
// звучит, выключается только при видимости выше FogOffMeters (гистерезис).
func ShouldSoundHorn(visibilityMeters int, hornOn bool) bool {
	if hornOn {
		return visibilityMeters < FogOffMeters
	}
	return visibilityMeters < FogOnMeters
}

