// NightsLeft оценивает, сколько ночей маяк продержится на батареях без подзарядки.
func NightsLeft(percent int, percentPerNight float64) float64 {
	if percentPerNight <= 0 {
		return 0
	}
	return float64(percent) / percentPerNight
}

