class TideTable:
    """High and low waters of one harbour, read from a CSV file of time and height."""

    def __init__(self, points: list[TidePoint]) -> None:
        self.points = sorted(points, key=lambda p: p.time)

    @classmethod
    def load(cls, path: Path) -> "TideTable":
        with path.open(newline="") as handle:
            rows = csv.reader(handle)
            return cls([TidePoint(datetime.fromisoformat(t), float(h)) for t, h in rows])

    def height_at(self, moment: datetime) -> float:
        """The water height at a moment, interpolated linearly between two table points."""
        before = max((p for p in self.points if p.time <= moment), key=lambda p: p.time)
        after = min((p for p in self.points if p.time >= moment), key=lambda p: p.time)
        if before.time == after.time:
            return before.height_m
        span = (after.time - before.time).total_seconds()
        part = (moment - before.time).total_seconds() / span
        return before.height_m + (after.height_m - before.height_m) * part

tidewater/berths.py: BerthAllocator
@dataclass
class BerthAllocator:
    berths: list[Berth] = field(default_factory=list)

    def allocate(self, vessel: Vessel) -> Berth:
        """Give the vessel the smallest free berth that fits it; ties go to the lower number."""
        candidates = [b for b in self.berths if b.occupant is None and b.fits(vessel)]
        if not candidates:
            raise NoBerthAvailable(f"no free berth fits {vessel.name}")
        best = min(candidates, key=lambda b: (b.length_m, b.number))
        best.occupant = vessel
        return best

    def release(self, number: int) -> Vessel | None:
        """Free the berth with this number and return the vessel that left it."""
        for berth in self.berths:
            if berth.number == number:
                vessel, berth.occupant = berth.occupant, None
                return vessel
        raise KeyError(number)

    def occupancy(self) -> float:
        """The share of berths that are taken, from 0 to 1."""
        if not self.berths:
            return 0.0
        taken = sum(1 for b in self.berths if b.occupant is not None)
        return taken / len(self.berths)

